  var FPS = 60;
  var PROC_CHANCE = 0.05;      // 5%
  var HEAL_PCT = 10.77;        // スキル発動者の最終最大HPの10.77%
  var HP_THRESHOLD = 90;       // 自分のHPが90%以上
