      var es = E.alive(E.enemies(u));
      for (var i = 0; i < es.length; i++) {
        E.damage(u, es[i], frame, { multiplierPct: ONEMORE_DMG, isDistributed: true });
      }

      // 1more適用時：基本バースト段階3の味方全体に攻撃力35.2%（3スタック）
      var team = E.team(u);
