  'use strict';

  var STANCE_ATKDMG_PCT = 20.45;   /* 原文: 攻撃ダメージ20.45%▲ */
  var STANCE_CHARGEDMG_PCT = 40;   /* 原文: チャージダメージ40%▲ */
  var ENGAGE_TRUEDMG_PCT = 370.08; /* 原文: 最終攻撃力の370.08%の防御力無視ダメージ */
  var STANCE_EXTRA_PCT = 450.89;   /* 原文: 最終攻撃力の450.89%の追加ダメージ */
