  var S1_SHOTS = 3;               /* 3発間維持 */

  var S2_PELLETS = 160;           /* ペレットが160回命中した時 */
  var S2_PIERCE_RANGE = 200;      /* 貫通範囲200%拡大：3発間 */
  var S2_SHOTS = 3;

  var FB_ATK = 75.24;             /* 攻撃力75.24%▲：持続（FB中のみ） */
  var FB_HIT = 40.68;             /* 命中率40.68%▲：持続（FB中のみ） */

